INSERT INTO `chat_fun_data` VALUES ('1633298471739817986', '报告', 'https://ai-chat-gpt.oss-cn-guangzhou.aliyuncs.com/upload/20230308/050763a580a1c5954550f436c3e651ae.png', 'report', '0', 'return {\r\n    color: \'88,241,236\',//rgb颜色  背景颜色    \r\n    textColor:\'#095C52\',//文本颜色\r\n    text:\'帮向{user}汇报{value},用于{scene},{length}长度\',//拼接文本 {value}用户输入的值\r\n    theme:\'报告\',//主题\r\n    title:\'想要汇报什么？\',//标题\r\n    tip: \'例如：今天工作\',\r\n    maxLength:1000,\r\n    shortcutList:[ //快捷选择配置\r\n        {\r\n            title:\'汇报对象\',\r\n            key:\'user\',\r\n            type:\'input\',\r\n            value:\'老板\'\r\n        },\r\n        {\r\n            title:\'场景\',\r\n            key:\'scene\',\r\n            type:\'input\',\r\n            value:\'工作报告\'\r\n        },\r\n        {\r\n            title:\'长度\',\r\n            key:\'length\',\r\n            type:\'checkbox\',\r\n            dicData:[\'较短\',\'中等\',\'较长\'],\r\n            value:\'较短\'\r\n        }\r\n    ]\r\n}', '000000', 1123598821738675201, '2023-03-08 10:47:55', 1123598821738675201, '2023-03-10 14:36:56', '1123598813738675201', 0, 0, '1633295146973757441', '1', '1', '0');
