INSERT INTO `chat_fun_data` VALUES ('1634013267837591553', '智能起名', 'https://ai-chat-gpt.oss-cn-guangzhou.aliyuncs.com/upload/20230310/1a48758d668bc158c1bc54827dda9511.png', 'name', '0', 'return { //例子\n    color: \'254,218,98\',//rgb颜色  背景颜色    \n    textColor:\'#6D5528\',//文本颜色\n    text: \'帮我起一个{value}风格，性别为{sex},姓氏为{surname}，五行属{five}的中文名字\',//拼接文本 {value}用户输入的值    \n    theme: \'起名\',//主题\n    title: \'想要什么风格的名字？\',//标题\n    maxLength: 1000,//最大输入文本数     \n    tip: \'例如：豪爽\',\n    shortcutList: [ //快捷选择配置  \n        {\n            title: \'性别\',\n            key: \'sex\',\n            type: \'checkbox\',\n            dicData: [\'男\', \'女\'],//控件字典\n            value: \'男\',//默认值\n        },\n        {\n            title: \'姓氏\',\n            key: \'surname\',\n            type: \'input\',//控件类型\n            value: \'陈\',//默认值\n        },\n        {\n            title: \'五行\',\n            key: \'five\',\n            type: \'input\',//控件类型\n            value: \'水、土\',//默认值 \n        }\n    ]\n}', '000000', 1123598821738675201, '2023-03-10 10:08:16', 1123598821738675201, '2023-03-10 14:15:19', '1123598813738675201', 0, 0, '1633766959784738817', '1', '4', '0');
INSERT INTO `chat_fun_data` VALUES ('1634015311252168706', '写检讨', 'https://ai-chat-gpt.oss-cn-guangzhou.aliyuncs.com/upload/20230310/042fd4f0f4945e5876a24e4561f4d525.png', 'review', '0', 'return { //例子\n    color: \'193,167,255\',//rgb颜色  背景颜色    \n    textColor:\'#282050\',//文本颜色\n    text: \'帮我写一篇{length}的向{user}的检讨,检讨场景{value}\',//拼接文本 {value}用户输入的值    \n    theme:\'写检讨\',//主题\n    title: \'简要描述下检讨场景\',//标题\n    tip: \'例如：没有完成作业\',\n    maxLength:1000,//最大输入文本数     \n    shortcutList: [ //快捷选择配置         \n        {\n            title: \'检讨对象\',\n            key: \'user\',\n            type: \'input\',//控件类型\n            value:\'老师\',//默认值\n        },\n        {\n            title: \'长度\',\n            key: \'length\',\n            type: \'checkbox\',\n            dicData: [\'较短\', \'中等\', \'较长\'],//控件字典\n            value:\'较短\',//默认值\n        }\n    ]\n}', '000000', 1123598821738675201, '2023-03-10 10:16:23', 1123598821738675201, '2023-03-10 14:09:58', '1123598813738675201', 0, 0, '1633766959784738817', '1', '5', '0');
