ost(`/${that.apiRequestHead}/cgform-api/${apiType}/1656235263237079042`, {\\r\\n        ...that.formData.outerData,\\r\\n        val: JSON.stringify(userData),\\r\\n    }).then(res => {\\r\\n        that.$message({\\r\\n            type: \\\"success\\\",\\r\\n            message: \\\"保存成功\\\"\\r\\n        })\\r\\n        that.getFormDataFun()\\r\\n    }).catch(() => {\\r\\n        that.loading = false\\r\\n    })\\r\\n})\\r\\n\",\"prop\":\"1664160444492_68570\"}],\"onlineFormFieldArr\":[],\"onlineSubFormData\":[],\"onlineSubFormField\":{}},\"class\":\"form-group\",\"prop\":\"group_1683712656258_30413\",\"labelWidth\":\"0px\"}],\"labelPosition\":\"right\",\"labelSuffix\":\"：\",\"labelWidth\":140,\"gutter\":0,\"dialogWidth\":\"80%\",\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":true,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"onlineFormFieldArr\":[],\"onlineSubFormData\":[],\"onlineSubFormField\":{},\"formStyle\":\"default\",\"isShowPrint\":false,\"jsEnhanceStr\":\"\\r\\n\\r\\nthat.loading = true\\r\\nthat.getFormDataFun = () => {\\r\\n    api.get(`/${that.apiRequestHead}/cgform-api/getData/1656235263237079042?code=tcsz_data&column=id&order=desc&pageNo=1&pageSize=10`).then(res => {\\r\\n        let data = res.data.records\\r\\n        if (data.length > 0) {\\r\\n            data = data[0]\\r\\n            let formData = JSON.parse(data.val)\\r\\n            console.log(formData)\\r\\n            that.formData = {\\r\\n                ...that.formData,\\r\\n                ...formData,\\r\\n                outerData: data\\r\\n            }\\r\\n            let timer = setInterval(() => {\\r\\n                let dom = that.$refs.tableControl\\r\\n                if (dom.length && dom[0].optinsToLoad) {\\r\\n                    clearInterval(timer)\\r\\n                    setTimeout(() => {\\r\\n                        dom[0].tableData = formData.cgtc_list\\r\\n                    }, 0)\\r\\n                }\\r\\n            }, 100)\\r\\n        } else {\\r\\n            that.formData = {\\r\\n                ...that.formData,\\r\\n                outerData: {\\r\\n                    name: \'套餐设置\',\\r\\n                    code: \'tcsz_data\',\\r\\n                    val: \'{}\',\\r\\n                }\\r\\n            }\\r\\n        }\\r\\n        that.loading = false\\r\\n    }).catch(error => {\\r\\n        that.loading = false\\r\\n    })\\r\\n}\\r\\nthat.getFormDataFun()\\r\\n\",\"cssEnhanceStr\":\".rcgl_szgl_jscz_shry_save{\\r\\n    margin-left: 50px;\\r\\n}\"}', 1, -1, '', -1, 1123598821738675201, 1123598813738675201, '2022-10-12 18:46:26', 1123598821738675201, '2023-05-11 09:30:26', 1, 0, '0');
