INSERT INTO `design_desform_head` VALUES (1632568223985381378, '000000', NULL, '人工充值会员', 'manual_recharge_vip', NULL, '{\"column\":[{\"value\":\"\",\"type\":\"input\",\"label\":\"手机号\",\"newLabel\":\"手机号\",\"tip\":\"\",\"labelTip\":\"\",\"span\":24,\"isMaxLength\":true,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":11,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"70%\"},\"prop\":\"wx_phone\",\"required\":true,\"rules\":[{\"pattern\":{},\"message\":\"手机号格式不匹配\"}],\"patternReg\":{},\"patternErrText\":\"请输入正确的手机号\"},{\"value\":\"add\",\"valueCone\":\"\",\"type\":\"select\",\"label\":\"类型\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"类型\",\"isLabel\":false,\"clearable\":true,\"dicData\":[{\"label\":\"增加\",\"value\":\"add\"},{\"label\":\"减少\",\"value\":\"sub\"}],\"dicDataFormat\":\"\",\"staticDicData\":[],\"dicDicData\":[],\"remoteDicData\":[],\"cascaderItem\":[],\"span\":24,\"display\":true,\"disabled\":false,\"dicOption\":\"static\",\"oldDicOption\":\"static\",\"isOneDefaultValue\":false,\"props\":{\"label\":\"label\",\"value\":\"value\"},\"class\":\"form-select\",\"style\":{\"width\":\"70%\"},\"prop\":\"wx_class\",\"required\":true,\"rules\":[{\"required\":true,\"message\":\"类型必须填写\"}]},{\"type\":\"number\",\"label\":\"燃料数\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"燃料数\",\"controls\":true,\"span\":24,\"display\":true,\"disabled\":false,\"class\":\"form-number\",\"controlsPosition\":\"\",\"isLabel\":false,\"style\":{\"width\":\"70%\"},\"prop\":\"rl_cou\",\"value\":0,\"minRows\":0,\"maxRows\":100000,\"required\":true,\"rules\":[{\"required\":true,\"message\":\"燃料数必须填写\"}]},{\"type\":\"number\",\"label\":\"天数\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"天数\",\"controls\":true,\"span\":24,\"display\":true,\"disabled\":false,\"class\":\"form-number\",\"controlsPosition\":\"\",\"isLabel\":false,\"style\":{\"width\":\"70%\"},\"prop\":\"wx_days\",\"value\":30,\"m