hat.loading = false\\r\\n            that.closeDialogForm(\'hidegetData\')\\r\\n        }).catch(() => {\\r\\n            that.loading = false\\r\\n        })\\r\\n    }\\r\\n})\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\",\"prop\":\"button_1678081731174_73505\",\"circle\":false,\"round\":false,\"plain\":false,\"buttonIcon\":\"el-icon-check\"}],\"labelPosition\":\"right\",\"labelSuffix\":\"：\",\"labelWidth\":100,\"gutter\":0,\"dialogWidth\":\"40%\",\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":true,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"onlineFormFieldArr\":[],\"onlineSubFormData\":[],\"onlineSubFormField\":{},\"formStyle\":\"default\",\"isShowPrint\":false,\"onlineFormName\":\"1632936001355468801\",\"jsEnhanceStr\":\"\",\"jsIncidentEnhanceStr\":\"let regphone = /^(13[0-9]|14[01456879]|15[0-35-9]|16[2567]|17[0-8]|18[0-9]|19[0-35-9])\\\\d{8}$/\\r\\nlet regmoney = /^\\\\+?[0-9]\\\\d*$/;\\r\\nthat.verify = [false, false]\\r\\nfunction hint(fieldName, hintText, index, reg) {\\r\\n    api.setFormOptions(fieldName, \'rules\', {\\r\\n        validator(rule, value, callback) {\\r\\n            if (value.length < 0) {\\r\\n                callback(new Error(`请输入${hintText}`));\\r\\n                that.verify[index] = false\\r\\n            } else if (!reg.test(value)) {\\r\\n                callback(new Error(`请输入正确的${hintText}`));\\r\\n                that.verify[index] = false\\r\\n            } else {\\r\\n                callback()\\r\\n                that.verify[index] = true\\r\\n            }\\r\\n        }\\r\\n    })\\r\\n}\\r\\n\\r\\nhint(\'wx_phone\', \'手机号\', 0, regphone)\\r\\nhint(\'wx_money\', \'金额\', 1, regmoney)\\r\\n\\r\\n\\r\\n\\r\\n/* api.setFormOptions(\'wx_phone\', \'rules\', {\\r\\n    validator(rule, value, callback) {\\r\\n        if (value.length <= 0) {\\r\\n            callback(new Error(`请输入手机号`));\\r\\n        } else if (!regphone.test(value)) {\\r\\n            callback(new Error(`请输入正确的手机号`));\\r\\n        } else {\\r\\n            callback()\\r\\n            that.verify[0] = true\\r\\n        }\\r\\n    }\\r\\n})\\r\\napi.setFormOptions(\'wx_money\', \'rules\', {\\r\\n    validator(rule, value, callback) {\\r\\n        if (value.length <= 0) {\\r\\n            callback(new Error(`请输入金额`));\\r\\n        } else if (!regmoney.test(value)) {\\r\\n            callback(new Error(`请输入正确的金额`));\\r\\n        } else {\\r\\n            callback()\\r\\n            that.verify[1] = true\\r\\n        }\\r\\n    }\\r\\n}) */\"}', 1, NULL, NULL, NULL, 1123598821738675201, 1123598813738675201, '2023-03-06 10:26:11', 1123598821738675201, '2023-09-16 11:59:55', 1, 0, '0');
