INSERT INTO `design_desform_head` VALUES (1633348339178942465, '000000', NULL, '系统佣金设置', 'yjgl_yjsz', NULL, '{\"column\":[{\"value\":\"\",\"type\":\"input\",\"label\":\"id\",\"newLabel\":\"id\",\"tip\":\"\",\"labelTip\":\"\",\"span\":24,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"rate_id\"},{\"type\":\"switch\",\"label\":\"开关\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"开关\",\"isLabel\":false,\"activeText\":\"1\",\"inactiveText\":\"0\",\"span\":24,\"display\":true,\"disabled\":false,\"value\":\"0\",\"class\":\"form-switch\",\"style\":{\"width\":\"100%\"},\"dicData\":[{\"label\":\"\",\"value\":\"0\"},{\"label\":\"\",\"value\":\"1\"}],\"prop\":\"open_flag\"},{\"value\":\"\",\"type\":\"input\",\"label\":\"一级佣金比例\",\"newLabel\":\"一级佣金比例\",\"tip\":\"\",\"labelTip\":\"\",\"span\":12,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"80%\"},\"prop\":\"one_rate\",\"append\":\"%\"},{\"value\":\"\",\"type\":\"input\",\"label\":\"二级佣金比例\",\"newLabel\":\"二级佣金比例\",\"tip\":\"\",\"labelTip\":\"\",\"span\":12,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"80%\"},\"prop\":\"two_rate\",\"append\":\"%\"},{\"type\":\"button\",\"label\":\"\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"按钮\",\"span\":24,\"labelWidth\":\"0\",\"isLabel\":true,\"display\":true,\"disabled\":false,\"buttonText\":\"保存\",\"class\":\"form-button control-align-center\",\"size\":\"medium\",\"buttonType\":\"primary\",\"clickFun\":\"that.formHandleSubmitFun().then(res=>{\\r\\n    console.log(\'that===\',that)\\r\\n    console.log(\'res==\',res)\\r\\n    let apiType = \\\"\\\"\\r\\n    that.loading = true\\r\\n    let data = {\\r\\n        open_flag: res.data.open_flag,\\r\\n        one_rate: res.data.one_rate / 100,\\r\\n        two_rate: res.data.two_rate / 100\\r\\n    }\\r\\n    // 是否有初始数据\\r\\n    if(that.is_init_rate){\\r\\n        apiType = \\\"editData\\\",\\r\\n        data = {\\r\\n            ...data,\\r\\n            id: res.data.rate_id,\\r\\n            create_user: res.data.create_user,\\r\\n            create_time: res.data.create_time,\\r\\n            is_deleted: res.data.is_deleted,\\r\\n            status: res.data.status,\\r\\n            update_user: res.data.update_user,\\r\\n            update_time: res.data.update_time,\\r\\n            tenant_id: res.data.tenant_id,\\r\\n            create_dept: res.data.create_dept\\r\\n        }\\r\\n    } else {\\r\\n        apiType = \\\"addData\\\"\\r\\n        that.is_init_rate = true\\r\\n    }\\r\\n    api.post(`/${that.apiRequestHead}/cgform-api/${apiType}/1633302730053091330`,data).then(res=>{\\r\\n        api.get(`/${that.apiRequestHead}/cgform-api/getData/1633302730053091330`).then(res=>{\\r\\n            api.setFormData(\'rate_id\',res.data.records[0].id)\\r\\n            api.setFormData(\'open_flag\',res.data.records[0].open_flag)\\r\\n            api.setFormData(\'one_rate\',res.data.records[0].one_rate*100)\\r\\n            api.setFormData(\'two_rate\',res.data.records[0].two_rate*100)\\r\\n            //\\r\\n            api.setFormData(\'create_user\',res.data.records[0].create_user)\\r\\n            api.setFormData(\'create_time\',res.data.records[0].create_time)\\r\\n            api.setFormData(\'is_deleted\',res.data.records[0].is_deleted)\\r\\n            api.setFormData(\'status\',res.data.records[0].status)\\r\\n            api.setFormData(\'update_user\',res.data.records[0].update_user)\\r\\n            api.setFormData(\'update_time\',res.data.records[0].update_time)\\r\\n            api.setFormData(\'tenant_id\',res.data.records[0].tenant_id)\\r\\n            api.setFormData(\'create_dept\',res.data.records[0].create_dept)\\r\\n        })\\r\\n        that.loading = false\\r\\n        that.$message.success(\'保存成功！\')\\r\\n    }).catch((err)=>{\\r\\n        that.loading = false\\r\\n        that.$message.warning(\'保存出错了！\')\\r\\n    })\\r\\n\\r\\n})\\r\\n\",\"prop\":\"button_1678255609482_20377\"},{\"type\":\"textarea\",\"label\":\"\",\"tip\":\"\",\"labelTip\":\"\",\"newLabel\":\"多行文本\",\"span\":24,\"isMaxLength\":false,\"isLabel\":true,\"showWordLimit\":false,\"maxlength\":0,\"minRows\":4,\"maxRows\":100,\"display\":true,\"disabled\":false,\"class\":\"form-textarea custom-textarea\",\"style\":{\"width\":\"100%\"},\"value\":\"例如：\\n        系统设置 一级：50%   二级：5%\\n\\t个人单独设置：\\n\\t\\tA用户设置了一级：80%  二级设置了10%\\n\\t\\tB用户设置了一级：70%  二级设置了15%\\n\\t关系：A -> B -> C -> D\\n\\n\\t如果A消费 100元\\n\\t\\t因为A没有上级，则没有分佣\\n\\t如果B消费了100元\\n\\t\\t因为针对了A设置了一个属于自己的比例，并且A是属于B的一级，所以系统的设置比例则失效，用自己的自定义设置 80%\\n\\t\\tA的分佣为：100*80% =80元\\n\\t如果C消费了100元\\n\\t\\t因为针对了A设置了一个属于自己的比例，并且A是属于C的二级，所以系统的设置比例则失效，用自己的自定义设置 10%\\n\\t\\t因为针对了B设置了一个属于自己的比例，并且B是属于C的一级，所以系统的设置比例则失效，用自己的自定义设置 70%\\n\\t\\tA的分佣为：100*10% =10元\\n\\t\\tB的分佣为：100*70% =70元\\n\\t如果D消费了100元\\n\\t\\t因为针对了A设置了一个属于自己的比例，并且A是属于D的三级，不存在分佣\\n\\t\\t因为针对了B设置了一个属于自己的比例，并且B是属于D的二级，所以系统的设置比例则失效，用自己的自定义设置 15%\\n\\t\\t因为针对了C没有设置自己的个人比例，所以用系统的比例，C是属于D的一级  50%\\n\\t\\tA的分佣为：0元\\n\\t\\tB的分佣为：100*15% =15元\\n\\t\\tC的分佣为：100*50% =50元\",\"prop\":\"textarea_1678264641058_28369\",\"placeholder\":\"\",\"labelWidth\":\"0px\",\"readonly\":true},{\"value\":\"\",\"type\":\"input\",\"label\":\"create_dept\",\"newLabel\":\"create_dept\",\"tip\":\"\",\"labelTip\":\"\",\"span\":8,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"create_d