INSERT INTO `design_desform_head` VALUES (1633397142930165762, '000000', 1633304324450648066, '自定义佣金设置', 'custom-yjsj', NULL, '{\"column\":[{\"value\":\"\",\"type\":\"input\",\"label\":\"手机号码\",\"newLabel\":\"手机号码\",\"tip\":\"\",\"labelTip\":\"\",\"icon\":\"icon-input\",\"span\":24,\"isMaxLength\":true,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":11,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"view_phone\",\"required\":true,\"rules\":[{\"required\":true,\"message\":\"手机号码必须填写\"}]},{\"value\":\"\",\"type\":\"input\",\"label\":\"一级比例\",\"newLabel\":\"一级比例\",\"tip\":\"\",\"labelTip\":\"\",\"icon\":\"icon-input\",\"span\":24,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"one_rate\",\"append\":\"%\",\"required\":true,\"rules\":[{\"required\":true,\"message\":\"一级比例必须填写\"}]},{\"value\":\"\",\"type\":\"input\",\"label\":\"二级比例\",\"newLabel\":\"二级比例\",\"tip\":\"\",\"labelTip\":\"\",\"icon\":\"icon-input\",\"span\":24,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"two_rate\",\"append\":\"%\",\"required\":true,\"rules\":[{\"required\":true,\"message\":\"二级比例必须填写\"}]},{\"value\":\"\",\"type\":\"input\",\"label\":\"备注\",\"newLabel\":\"备注\",\"tip\":\"\",\"labelTip\":\"\",\"icon\":\"icon-input\",\"span\":24,\"isMaxLength\":false,\"isLabel\":false,\"showWordLimit\":false,\"maxlength\":0,\"display\":true,\"disabled\":false,\"class\":\"form-input\",\"authComKey\":\"\",\"authField\":\"\",\"clearable\":true,\"style\":{\"width\":\"100%\"},\"prop\":\"remark\"}],\"labelPosition\":\"left\",\"labelSuffix\":\"：\",\"labelWidth\":120,\"gutter\":0,\"dialogWidth\":\"40%\",\"menuBtn\":true,\"submitBtn\":true,\"submitText\":\"提交\",\"emptyBtn\":true,\"emptyText\":\"清空\",\"menuPosition\":\"center\",\"onlineFormFieldArr\":[],\"onlineSubFormData\":[],\"onlineSubFormField\":{},\"formStyle\":\"default\",\"isShowPrint\":false,\"onlineFormName\":\"1633304324450648066\",\"jsEnhanceStr\":\"let result = api.getFormData(\'view_phone\')\\r\\nif (result.length >= 11) {\\r\\n    \\r\\n    api.setFormMoreOptions(\'view_phone\', {\\r\\n        disabled: true\\r\\n    })\\r\\n    let one_rate = api.getFormData(\'one_rate\')\\r\\n    let two_rate = api.getFormData(\'two_rate\')\\r\\n    api.setFormData(\'one_rate\', one_rate*100)\\r\\n    api.setFormData(\'two_rate\', two_rate*100)\\r\\n    api.disposeFormDataEnhance(form => {\\r\\n        return new Promise((resolve, reject) => {\\r\\n            if (that.custom.every(item => item)) {\\r\\n                form.one_rate = form.one_rate / 100\\r\\n                form.two_rate = form.two_rate / 100\\r\\n                resolve(form)\\r\\n            }\\r\\n        })\\r\\n    })\\r\\n} else {\\r\\n    api.disposeFormDataEnhance(form => {\\r\\n        return new Promise((resolve, reject) => {\\r\\n            if (that.custom.every(item => item)) {\\r\\n                form.one_rate = form.one_rate / 100\\r\\n                form.two_rate = form.two_rate / 100\\r\\n                resolve(form)\\r\\n            }\\r\\n        })\\r\\n    })\\r\\n}\\r\\n\\r\\n\\r\\n\\r\\n\",\"jsIncidentEnhanceStr\":\"let regphone = /^(13[0-9]|14[01456879]|15[0-35-9]|16[2567]|17[0-8]|18[0-9]|19[0-35-9])\\\\d{8}$/\\r\\nlet regnum = /^([1-9]\\\\d?|100)$/;\\r\\n\\r\\nthat.custom = [false, false, false]\\r\\nfunction hint(fieldName, hintText, index, reg) {\\r\\n    api.setFormOptions(fieldName, \'rules\', {\\r\\n        validator(rule, value, callback) {\\r\\n            if (value.length <= 0) {\\r\\n                callback(new Error(`请输入${hintT