INSERT INTO `onl_cgform_enhance_js` VALUES (1628948079405002753, '000000', '// test_infoCollection\r\ncreated(that){\r\n    that.tableOption = {\r\n        ...that.tableOption,\r\n        stripe: true,\r\n        editBtnText: \'审批\'\r\n    }\r\n},\r\ncolumnInit(that){\r\n    that.setTableOptionsFun(\'test_info\',{\r\n        minWidth: 140,\r\n        overHidden: true\r\n    }),\r\n    that.setTableOptionsFun(\'test_class\',{\r\n        minWidth: 80\r\n    }),\r\n    that.setTableOptionsFun(\'test_name\',{\r\n        minWidth: 100\r\n    }),\r\n    that.setTableOptionsFun(\'test_range\',{\r\n        minWidth: 140\r\n    }),\r\n    that.setTableOptionsFun(\'test_tel\',{\r\n        // 文本格式化\r\n        formatter:(row,value,label,column)=>{return \'+86 \'+value}\r\n    })\r\n},\r\n// testApprovalBtn(that,row){\r\n//     that.isFormViewControl=true\r\n//     that.FormViewControlOption={\r\n//         ...that.FormViewControlOption,\r\n//         viewObj: {\r\n//             isShow:true, //是否显示表单\r\n//             type:\'dialog\', //弹窗类型  表单:view  抽屉:drawer 弹窗:dialog\r\n//             title:\'审批信息\', //标题文本\r\n//             width:\'50%\', //弹窗宽度\r\n//             destroy:false,//关闭时是否销毁元素\r\n//             isGetData:false,//是否需要获取数据\r\n//         	carryInit:false,//是否需要重新初始化表单配置\r\n//         },\r\n//         formId: \'1628601390173376514\', // 表单设计id\r\n//         formOpenType: \'edit\', // 当前弹窗类型 add edit view\r\n//         actionData: {\r\n//             type: \'hidegetData\',\r\n//             noRouter: true,\r\n//             closeType: \'hidegetData\',\r\n//             isMessage: true\r\n//         },\r\n//         btnPermissions:{\r\n//             cancelBtn: true\r\n//         },\r\n//         defaultData: {\r\n//             id: row.id,\r\n//             test_name: row.test_name,\r\n//             test_class: row.test_class,\r\n//             test_tel: row.test_tel,\r\n//             test_range: row.test_range,\r\n//             test_date: row.test_date,\r\n//             test_info: row.test_info,\r\n//             test_status: row.test_status\r\n//         },\r\n//     }\r\n//     // alert(\'审批\')\r\n// },\r\ncellStyle(that,obj){\r\n    if(obj.column.label==\'状态\'){\r\n        if (obj.row.test_status==\'已批准\') {\r\n            return {\r\n                color: \'#00f\',\r\n                fontWeight: \'700\'\r\n            }\r\n        }\r\n        if (obj.row.test_status==\'未批准\') {\r\n            return {\r\n                color: \'#f00\',\r\n                fontWeight: \'700\'\r\n            }\r\n        }\r\n    }  \r\n},\r\nselectionChange(that,data){\r\n    let len = data.length\r\n    if(len){\r\n        console.log(\'data\',typeof that.tableSelectData)\r\n        let time = that.simpleDateFormat(new Date(), \'yyyy-MM-dd hh:mm:ss\')\r\n        alert(time+\'\\n现选中\'+len+\'条信息\\ndata->\'+len+\'\\n已选中\'+that.tableSelectId)\r\n    } \r\n}\r\n// selectable(row,index){\r\n//     if(row.test_status==\'已批准\'){\r\n//         return false \r\n//     }\r\n//     return true\r\n// }\r\n\r\n\r\n\r\n\r\n', 'list', NULL, 1628638590567002113, 1123598821738675201, 1123598813738675201, '2023-02-24 10:41:01', 1123598821738675201, '2023-11-01 14:59:53', 1, 0);
INSERT INTO `onl_cgform_enhance_js` VALUES (1628949370000732161, '000000', 'created(that){\r\n    that.tableOption = {\r\n        ...that.tableOption,\r\n        menuWidth: 150\r\n    }\r\n},\r\ncolumnInit(that){\r\n    that.setTableOptionsFun(\"message_a\",{\r\n        overHidden: true\r\n    }),\r\n    that.setTableOptionsFun(\"message_q\",{\r\n        overHidden: true\r\n    })\r\n}', 'list', NULL, 1626103377517432834, 1123598821738675201, 1123598813738675201, '2023-02-24 10:46:09', 1123598821738675201, '2023-03-08 10:11:37', 1, 0);
