INSERT INTO `onl_cgform_enhance_js` VALUES (1632560460672610306, '000000', 'columnInit(that){\r\n    that.setTableOptionsFun(\'pay_status\', {\r\n        searchValue: \'1\'\r\n    })\r\n    that.isFormViewControl = true //启用控件\r\n    that.FormViewControlOption = {\r\n        ...that.FormViewControlOption,\r\n        viewObj: {\r\n            isShow: false, //是否显示表单\r\n            type: \'dialog\', //弹窗类型  表单:view  抽屉:drawer 弹窗:dialog\r\n            title: \'充值会员\', //标题文本\r\n            width: \'40%\', //弹窗宽度\r\n            destroy: true,//关闭时是否销毁元素\r\n            isGetData: false,//是否需要获取数据\r\n            carryInit: false,//是否需要重新初始化表单配置\r\n        },\r\n        formId: \'1632568223985381378\', //表单设计id\r\n        formOpenType: \'add\', //当前弹窗类型 add edit view\r\n        actionData: {\r\n            type: \'returnData\', //提交类型\r\n            noRouter: true,//不启用路由配置\r\n            closeType: \'hidegetData\',//关闭类型 hide:关闭 hidegetData:关闭并重新获取表格数据\r\n            isMessage: false,//是否有提交成功提示\r\n        },\r\n        btnPermissions: { //是否显示按钮\r\n            clearBtn: false, //清空按钮\r\n            cancelBtn: false, //取消按钮\r\n            submitBtn: false, //提交按钮\r\n        }\r\n    }\r\n},\r\nmanualRecharge(that, row){\r\n    that.FormViewControlOption.viewObj.isShow = true;\r\n}', 'list', NULL, 1628605998119641090, 1123598821738675201, 1123598813738675201, '2023-03-06 09:55:20', 1123598821738675201, '2023-03-11 15:52:45', 1, 0);
INSERT INTO `onl_cgform_enhance_js` VALUES (1632580569998929922, '000000', 'loaded(that){\r\n  console.log(that,77777)  \r\n},\r\neditSubmit(that, row){\r\n    return new Promise((res, rej) => {\r\n        console.log(row,66666)\r\n        res()\r\n    })\r\n\r\n}\r\n', 'list', NULL, 1632575955559854081, 1123598821738675201, 1123598813738675201, '2023-03-06 11:15:14', 1123598821738675201, '2023-03-06 17:26:30', 1, 0);
