INSERT INTO `onl_cgform_enhance_js` VALUES (1633286972539502594, '000000', 'created(that){\r\n    that.tableOption = {\r\n        ...that.tableOption,\r\n        menuWidth: 180\r\n    }\r\n}', 'list', NULL, 1631552449833410562, 1123598821738675201, 1123598813738675201, '2023-03-08 10:02:14', 1123598821738675201, '2023-03-08 10:09:52', 1, 0);
