-- ----------------------------
-- Table structure for chat_log_message
-- ----------------------------
DROP TABLE IF EXISTS `chat_log_message`;
CREATE TABLE `chat_log_message`  (
  `id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `wxuser_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信用户id',
  `tenant_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '000000' COMMENT '租户id',
  `create_user` bigint NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `create_dept` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人部门',
  `status` int NULL DEFAULT 0 COMMENT '状态',
  `is_deleted` int NULL DEFAULT 0 COMMENT '是否已删除',
  `blade_user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `message_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息类型',
  `message_time` datetime NULL DEFAULT NULL COMMENT '消息时间',
  `message_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '消息内容',
  `pid` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父级别',
  `view_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '显示方式',
  `model_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类',
  `api_account_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'chatgpt账号id',
  `is_hot` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '是否热门',
  `hot_time` datetime NULL DEFAULT NULL COMMENT '热门时间',
  `context_flag` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '是否支持上下文',
  `voice_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文本语音地址',
  `chat_list_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '随便聊' COMMENT '聊天列表名',
  `chat_list_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '聊天列表id',
  `chat_store_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '聊天收藏表id',
  `store_status` int NULL DEFAULT 1 COMMENT '收藏状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ind_time`(`wxuser_id` ASC, `create_time` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `ind_id`(`id` ASC) USING BTREE,
  INDEX `ind_type`(`message_type` ASC, `message_time` ASC, `model_type` ASC) USING BTREE,
  INDEX `ind_list`(`id` ASC, `wxuser_id` ASC, `message_type` ASC, `message_time` ASC, `pid` ASC, `model_type` ASC) USING BTREE,
  INDEX `ind_all`(`id` ASC, `wxuser_id` ASC, `create_time` ASC, `blade_user_id` ASC, `message_type` ASC, `message_time` ASC, `pid` ASC, `model_type` ASC) USING BTREE,
  INDEX `ind_wuserid`(`id` ASC, `wxuser_id` ASC, `is_deleted` ASC) USING BTREE,
  INDEX `ind_pid`(`message_type` ASC, `pid` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消息列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of chat_log_message
-- ----------------------------

